import csv
from datetime import datetime

# Build full picture
with open('/app/dataset/product_catalog.csv') as f:
    reader = csv.DictReader(f)
    prods = {}
    for r in reader:
        r['unit_price'] = float(r['unit_price'].replace(',', '.'))
        r['max_safe_temp_c'] = float(r['max_safe_temp_c'])
        prods[r['product_id']] = r

with open('/app/dataset/warehouse_dispatches.csv') as f:
    reader = csv.DictReader(f)
    dispatches = []
    for d in reader:
        pid = d['product_id']
        if pid not in prods:
            # try ean
            for k, v in prods.items():
                if v['ean_code'] == pid:
                    pid = k
                    break
        dispatches.append({
            'ts': datetime.strptime(d['timestamp'], '%Y-%m-%d %H:%M:%S'),
            'product_id': pid,
            'qty': int(d['quantity']),
        })

# look for meat dispatches on 18 july
meat_on_18 = []
for dis in dispatches:
    if dis['ts'].date().day == 18:
        prod = prods[dis['product_id']]
        if prod['storage_category'] == 'Meat':
            meat_on_18.append(dis)
meat_on_18.sort(key=lambda x: x['ts'])
for m in meat_on_18:
    print(m, prods[m['product_id']]['name'], prods[m['product_id']]['price'])
