import csv
from datetime import datetime

with open('/app/dataset/product_catalog.csv') as f:
    reader = csv.DictReader(f)
    prods = {}
    for r in reader:
        r['unit_price'] = float(r['unit_price'].replace(',', '.'))
        r['max_safe_temp_c'] = float(r['max_safe_temp_c'])
        r['storage_category'] = r['storage_category']
        prods[r['product_id']] = r

with open('/app/dataset/warehouse_dispatches.csv') as f:
    reader = csv.DictReader(f)
    dispatches = []
    for d in reader:
        pid = d['product_id']
        if pid not in prods:
            for k, v in prods.items():
                if v['ean_code'] == pid:
                    pid = k
                    break
        prod = prods[pid]
        dispatches.append({
            'ts': datetime.strptime(d['timestamp'], '%Y-%m-%d %H:%M:%S'),
            'product_id': pid,
            'qty': int(d['quantity']),
            'cat': prod['storage_category'],
            'price': prod['unit_price'],
            'name': prod['name'],
            'max_t': prod['max_safe_temp_c']
        })

# summarize by category for 18 July dispatches
by_cat = {}
for dis in dispatches:
    if dis['ts'].date().day == 18:
        by_cat[dis['cat']] = by_cat.get(dis['cat'], 0) + dis['qty'] * dis['price']
